export function areaForLocation(state: string, city: string): string | null {
  if (state.toUpperCase() !== 'CA') return null;
  const text = city.toLowerCase();
  if (SOCAL_KEYS.some(k => text.includes(k))) return 'SoCal';
  if (NORCAL_KEYS.some(k => text.includes(k))) return 'NorCal';
  return null;
}
